#!/usr/bin/env ruby
# PostgreSQL 17/18 descartável, bootstrap ADR-036 pronto (com vetra_relay); DATABASE_URL administrativa.
# VETRA_APP_PASSWORD e VETRA_RELAY_PASSWORD: senhas dos logins reais, se necessárias. VETRA_PG_DUMP: pg_dump da versão.
# Aplica os planos pelo db:migrate como vetra_migrator e exercita o registro de idempotência da operação (ADR-016 e
# ADR-043) como vetra_app e vetra_relay: reivindicação e repetição, entrada e principal diferentes, rollback, duas
# transações na mesma chave, lock_timeout, isolamento de tenant, unicidade com tenant nulo (contexto global), privilégios,
# limites de chave e de resultado, origem por evento e a purga por origem e idade. Não altera papéis nem artefatos.
require_relative 'sonda_relay'

class IdempotencyProbe < RelayProbe
  IDEMPOTENCY_EXAMPLES = %w[mini_crm blog chat].freeze
  TABLE = 'vetra.idempotency'

  def run
    @admin = PG.connect(@url)
    @admin.exec('SET client_min_messages = warning')
    @admin.exec(Vetra::SQL::Context.role_guard)
    before = roles
    IDEMPOTENCY_EXAMPLES.each do |example|
      @example = example
      @root = File.expand_path("../examples/#{example}", __dir__)
      @linked = Vetra::Graph::Compiler.new(root: @root).link
      @connection = create_database
      @database_name = @databases.last
      check_case('db:migrate aplica todos os planos, e o último traz a idempotência') do
        migrate.status == :applied && as_superuser("SELECT to_regclass('#{TABLE}')::text AS name").first['name'] == TABLE
      end
      open_runtime
      if tenant?
        provision('runtime', @secret)
        @work = Vetra::Data::UnitOfWork.new(@runtime, issuer: Vetra::Data::ContextIssuer.new(kid: 'runtime', secret: @secret))
        @tenants, @actors = [@tenant, SecureRandom.uuid], [@actor, SecureRandom.uuid]
      else
        @work = Vetra::Data::UnitOfWork.new(@runtime, scope: :global)
      end
      @other_actor = SecureRandom.uuid
      open_relay
      claim_checks
      concurrency_checks
      database_checks
      purge_checks
      check_case('nenhum statement nomeado no relay nem no runtime') do
        @relay_db[:pg_prepared_statements].count.zero? && @runtime[:pg_prepared_statements].count.zero?
      end
      close_relay
      close_runtime
    end
    check('nenhum papel global mudou') { roles == before }
    puts "#{@results.count(true)}/#{@results.size} verificações passaram (PostgreSQL #{@admin.server_version})."
    @results.all?
  ensure
    close_relay
    close_runtime
    if @admin
      @databases.reverse_each { |name| @admin.exec("DROP DATABASE IF EXISTS #{PG::Connection.quote_ident(name)} WITH (FORCE)") }
      @admin.close
    end
  end

  private

  def open_runtime
    # Duas ou mais conexões: as verificações de concorrência usam transações simultâneas.
    @runtime = Vetra::Data.connect({ adapter: :postgres, host: @admin.host, hostaddr: @admin.hostaddr, port: @admin.port,
                                    database: @database_name, password: ENV.fetch('VETRA_APP_PASSWORD', '') }, max_connections: 4)
    @runtime.extend(ContextCounter)
  end

  def outbox?
    Vetra::SQL::Outbox.needed?(@linked.document)
  end

  def new_key
    "chave-#{SecureRandom.hex(6)}"
  end

  # Uma operação como a borda confiável a faria: reivindica na etapa 4, executa e guarda o resultado na etapa 7.
  def operation(key:, input: { 'nome' => 'A' }, actor: @actor, tenant: @tenant, command: 'crm.create_lead', result: { 'ok' => true },
                executed: nil, origin: :adapter, event: nil, before: nil, between: nil, fail_after: false)
    claims = { op_id: SecureRandom.uuid, cmd: command, actor_id: actor }
    claims[:tenant_id] = tenant if tenant?
    @work.transaction(**claims) do |unit|
      before&.call(unit)
      idempotency = Vetra::Data::Idempotency.new(unit)
      claim = idempotency.claim!(command: command, key: key, input: input, origin: origin, event: event)
      next [:replay, claim.result] if claim.replay
      executed&.push(key)
      between&.call
      idempotency.complete!(claim, result)
      raise 'falha depois da reivindicação' if fail_after
      [:new, result]
    end
  end

  # O check exige `true`: raises só diz se o erro esperado veio; capture devolve o erro para inspeção.
  def raises(klass, &block)
    !capture(klass, &block).nil?
  end

  def capture(klass)
    yield
    nil
  rescue klass => error
    error
  end

  # Como o check herdado, e com a causa à vista quando VETRA_SONDA_DEBUG está definida.
  def check(label)
    ok = yield == true
    @results << ok
    puts "#{ok ? 'OK' : 'FALHA'}: #{label}"
  rescue StandardError => error
    @results << false
    warn "FALHA: #{label} (#{error.class}#{": #{error.message.lines.first&.strip}" if ENV['VETRA_SONDA_DEBUG']})"
    warn error.backtrace.first(5).join("\n") if ENV['VETRA_SONDA_DEBUG']
  end

  def pg_state(expected)
    yield
    false
  rescue PG::Error => error
    error.result&.error_field(PG::PG_DIAG_SQLSTATE) == expected
  end

  def rows_of(key)
    as_superuser("SELECT count(*) AS n FROM #{TABLE} WHERE key = $1", [key]).first['n'].to_i
  end

  def claim_checks
    check_case('a chave nova executa e guarda; a repetição devolve o resultado sem executar de novo') do
      key, executed = new_key, []
      first = operation(key: key, executed: executed, result: { 'id' => 1 })
      second = operation(key: key, executed: executed)
      first == [:new, { 'id' => 1 }] && second == [:replay, { 'id' => 1 }] && executed == [key] && rows_of(key) == 1
    end
    check_case('a mesma chave com outra entrada é recusada, sem devolver o resultado guardado') do
      key = new_key
      operation(key: key, result: { 'segredo' => 'x' })
      error = capture(Vetra::Data::IdempotencyKeyReuse) { operation(key: key, input: { 'nome' => 'B' }) }
      error && !error.message.include?('segredo') && !error.diagnostics.first.message.include?('x')
    end
    check_case('a mesma chave por outro principal é recusada da mesma forma') do
      key = new_key
      operation(key: key)
      raises(Vetra::Data::IdempotencyKeyReuse) { operation(key: key, actor: @other_actor) }
    end
    check_case('o mesmo código em outro comando é outra chave') do
      key = new_key
      operation(key: key) == [:new, { 'ok' => true }] && operation(key: key, command: 'crm.outro') == [:new, { 'ok' => true }]
    end
    check_case('a ordem das chaves da entrada não muda o hash') do
      key = new_key
      operation(key: key, input: { 'a' => 1, 'b' => { 'x' => 1, 'y' => 2 } })
      operation(key: key, input: { 'b' => { 'y' => 2, 'x' => 1 }, 'a' => 1 }).first == :replay
    end
    check_case('o resultado de uma operação que falha depois de reivindicar não fica guardado') do
      key = new_key
      raises(RuntimeError) { operation(key: key, fail_after: true) }
      rows_of(key).zero? && operation(key: key) == [:new, { 'ok' => true }]
    end
    check_case('um ator de sistema usa a mesma chave com o próprio principal, e outro handler é recusado') do
      next true unless tenant?
      key = new_key
      claims = ->(handler) { { op_id: SecureRandom.uuid, cmd: 'crm.create_lead', tenant_id: @tenant, system_actor: handler } }
      run = lambda do |handler|
        @work.transaction(**claims.call(handler)) do |unit|
          idem = Vetra::Data::Idempotency.new(unit)
          claim = idem.claim!(command: 'crm.create_lead', key: key, input: { 'n' => 1 })
          idem.complete!(claim, { 'ok' => true }) unless claim.replay
          claim.replay
        end
      end
      run.call('crm.on_lead_won') == false && run.call('crm.on_lead_won') == true &&
        raises(Vetra::Data::IdempotencyKeyReuse) { run.call('crm.on_outro') }
    end
    check_case('entrada que não é JSON, chave e origem inválidas são recusadas antes do SQL') do
      bad_input = raises(Vetra::Data::Error) { operation(key: new_key, input: { 'x' => Float::NAN }) }
      bad_keys = ['', ' ', 'a b', 'á', 'x' * 256, "a\nb", nil].all? { |key| raises(Vetra::Data::Error) { operation(key: key) } }
      bad_origin = raises(Vetra::Data::Error) { operation(key: new_key, origin: :event) }
      bad_input && bad_keys && bad_origin
    end
    check_case('o resultado guardado cabe em 64 KiB e é JSON; o banco decide a fronteira') do
      key = new_key
      big = capture(Vetra::Data::Error) { operation(key: key, result: { 'x' => 'a' * 70_000 }) }
      # 65.536 bytes em JSON compacto passam pelo filtro de Ruby, mas o jsonb::text tem um espaço a mais: o CHECK recusa e o erro
      # sai como o mesmo diagnóstico, sem a mensagem do driver.
      edge = capture(Vetra::Data::Error) { operation(key: key, result: { 'x' => 'a' * 65_528 }) }
      big&.diagnostics&.first&.code == 'data_idempotency_result' && edge&.diagnostics&.first&.code == 'data_idempotency_result' &&
        !edge.message.include?('check') && rows_of(key).zero? && operation(key: key, result: { 'x' => 'a' * 60_000 }).first == :new
    end
    check_case('o teto vale sobre o jsonb normalizado: chaves repetidas e números reescritos que encolhem são aceitos') do
      key = new_key
      # O JSON compacto passa de 64 KiB, mas o jsonb guarda só a última chave repetida: cabe, e o banco aceita.
      repeated = { 'x' => 'a' * 65_528, x: 1 }
