      claims = { op_id: SecureRandom.uuid, cmd: 'crm.create_lead', actor_id: @actor }
      claims[:tenant_id] = @tenant if tenant?
      old_claim = @work.transaction(**claims) do |unit|
        idem = Vetra::Data::Idempotency.new(unit)
        claim = idem.claim!(command: 'crm.create_lead', key: key, input: {})
        idem.complete!(claim, { 'ok' => 1 })
        claim
      end
      refused = lambda do |&block|
        @work.transaction(**claims.merge(op_id: SecureRandom.uuid)) do |unit|
          block.call(unit, Vetra::Data::Idempotency.new(unit))
        end
        false
      rescue Vetra::Data::Error => error
        error.diagnostics.first.code == 'data_idempotency_state'
      end
      replayed = refused.call { |unit, idem| idem.complete!(idem.claim!(command: 'crm.create_lead', key: key, input: {}), { 'x' => 1 }) }
      stale = refused.call { |_unit, idem| idem.complete!(old_claim, { 'x' => 2 }) }
      forged = refused.call { |_unit, idem| idem.complete!(Vetra::Data::Idempotency::Claim.new(id: old_claim.id, replay: false, result: nil), { 'x' => 3 }) }
      # Contra uma linha AINDA SEM resultado: o claim fabricado tem os mesmos valores do verdadeiro e mesmo assim não vale.
      look_alike = refused.call do |_unit, idem|
        real = idem.claim!(command: 'crm.create_lead', key: new_key, input: {})
        idem.complete!(Vetra::Data::Idempotency::Claim.new(id: real.id, replay: false, result: nil), { 'x' => 5 })
      end
      twice = refused.call do |_unit, idem|
        claim = idem.claim!(command: 'crm.create_lead', key: new_key, input: {})
        idem.complete!(claim, {})
        idem.complete!(claim, { 'x' => 4 })
      end
      stored = as_superuser("SELECT result::text AS r FROM #{TABLE} WHERE key = $1", [key]).first['r']
      replayed && stale && forged && look_alike && twice && stored == '{"ok": 1}'
    end
  end

  def concurrency_checks
    check_case('duas transações na mesma chave: a segunda espera a primeira confirmar e devolve o resultado dela') do
      key, executed, ready = new_key, Queue.new, Queue.new
      first = Thread.new { operation(key: key, executed: executed, between: -> { ready << true; sleep 0.6 }, result: { 'id' => 7 }) }
      ready.pop
      started = Process.clock_gettime(Process::CLOCK_MONOTONIC)
      second = Thread.new { operation(key: key, executed: executed) }
      outcomes = [first.value, second.value]
      elapsed = Process.clock_gettime(Process::CLOCK_MONOTONIC) - started
      outcomes == [[:new, { 'id' => 7 }], [:replay, { 'id' => 7 }]] && executed.size == 1 && elapsed >= 0.25
    end
    check_case('se a primeira transação desfaz, a segunda fica com a chave e executa') do
      key, executed, ready = new_key, Queue.new, Queue.new
      first = Thread.new do
        raises(RuntimeError) { operation(key: key, executed: executed, between: -> { ready << true; sleep 0.5 }, fail_after: true) }
      end
      ready.pop
      second = Thread.new { operation(key: key, executed: executed) }
      first.value && second.value == [:new, { 'ok' => true }] && executed.size == 2 && rows_of(key) == 1
    end
    check_case('passado o lock_timeout, a espera vira conflito (409)') do
      key, ready, release = new_key, Queue.new, Queue.new
      first = Thread.new { operation(key: key, between: -> { ready << true; release.pop }) }
      ready.pop
      begin
        error = capture(Vetra::Data::Conflict) do
          operation(key: key, before: ->(unit) { unit.access(multi_tenant: tenant?) { |db| db.run("SET LOCAL lock_timeout = '200ms'") } })
        end
      ensure
        # Solta a primeira transação mesmo se a verificação falhar: ela não pode ficar presa à espera do fim da sonda.
        release << true
        first.join
      end
      error && error.kind == :lock_timeout && rows_of(key) == 1
    end
    check_case('muitas transações na mesma chave executam o call uma vez só') do
      key, executed = new_key, Queue.new
      outcomes = Array.new(4) { Thread.new { operation(key: key, executed: executed) } }.map(&:value)
      outcomes.count { |kind, _| kind == :new } == 1 && outcomes.count { |kind, _| kind == :replay } == 3 && executed.size == 1
    end
  end

  def database_checks
    check_case('a mesma chave com tenant nulo é única (NULLS NOT DISTINCT), no contexto global e nos demais') do
      key = new_key
      insert = "INSERT INTO #{TABLE} (tenant_id, command, key, origin, input_hash) VALUES (NULL, 'sonda.nula', $1, 'adapter', decode(repeat('00', 32), 'hex'))"
      @connection.exec_params(insert, [key])
      pg_state('23505') { @connection.exec_params(insert, [key]) } && rows_of(key) == 1
    end
    if tenant?
      check_case('o tenant isola as chaves: a mesma chave em outro tenant é outra, e cada um só enxerga as suas') do
        key = new_key
        a = operation(key: key, tenant: @tenant)
        b = operation(key: key, tenant: @tenants.last, actor: @actors.last)
        counts = [@tenant, @tenants.last].map do |tenant|
          @work.transaction(tenant_id: tenant, actor_id: @actor, op_id: SecureRandom.uuid, cmd: 'crm.create_lead') do |unit|
            unit.access(multi_tenant: true) { |db| db[Sequel[:vetra][:idempotency]].where(key: key).count }
          end
        end
        a.first == :new && b.first == :new && counts == [1, 1] && rows_of(key) == 2
      end
      check_case('um tenant não grava a chave de outro: o WITH CHECK recusa com 42501') do
        sql = "INSERT INTO #{TABLE} (tenant_id, command, key, origin, input_hash) VALUES ('#{SecureRandom.uuid}', 'x', 'k-#{SecureRandom.hex(3)}', 'adapter', decode(repeat('00', 32), 'hex'))"
        denied_app(sql)
      end
    end
    check_case('a aplicação grava a chave e atualiza só o resultado; não apaga, não esvazia nem define id e created_at') do
      hash = "decode(repeat('00', 32), 'hex')"
      [ "DELETE FROM #{TABLE}", "TRUNCATE #{TABLE}", "UPDATE #{TABLE} SET input_hash = input_hash",
        "UPDATE #{TABLE} SET principal = principal", "UPDATE #{TABLE} SET created_at = now()",
        "INSERT INTO #{TABLE} (created_at, command, key, origin, input_hash) VALUES (now(), 'x', 'k1', 'adapter', #{hash})"
      ].all? { |sql| denied_app(sql) } &&
        denied_app("INSERT INTO #{TABLE} (id, command, key, origin, input_hash) VALUES (1, 'x', 'k2', 'adapter', #{hash})", '428C9') &&
        # Com OVERRIDING SYSTEM VALUE o reescritor deixa passar e sobra só o privilégio por coluna: sem o GRANT de `id`, 42501.
        denied_app("INSERT INTO #{TABLE} (id, command, key, origin, input_hash) OVERRIDING SYSTEM VALUE VALUES (1, 'x', 'k9', 'adapter', #{hash})")
    end
    check_case('o banco recusa chave fora do formato, resultado acima de 64 KiB e origem incoerente (23514)') do
      hash = "decode(repeat('00', 32), 'hex')"
      base = "INSERT INTO #{TABLE} (command, key, origin, input_hash"
      cases = [
        "#{base}) VALUES ('x', 'com espaço', 'adapter', #{hash})",
        "#{base}) VALUES ('x', '#{'k' * 256}', 'adapter', #{hash})",
        "#{base}) VALUES ('', 'k3', 'adapter', #{hash})",
        "#{base}) VALUES ('x', 'k4', 'adapter', decode('00', 'hex'))",
        "#{base}, handler) VALUES ('x', 'k5', 'adapter', #{hash}, 'blog.h')",
        "#{base}, result) VALUES ('x', 'k6', 'adapter', #{hash}, to_jsonb(repeat('a', 70000)))"
      ]
      cases += ["#{base}) VALUES ('x', 'k7', 'event', #{hash})"] if outbox?
      cases << "#{base}) VALUES ('x', 'k8', 'event', #{hash})" unless outbox?
      cases.all? { |sql| pg_state('23514') { @connection.exec(sql) } }
    end
  end

  def seed(origin:, age_hours:, command: 'sonda.purga', event: nil)
    key = new_key
    @connection.exec_params(<<~SQL, [@tenant_for_seed, command, key, origin, age_hours.to_s, event&.fetch(:handler), event&.fetch(:event_id), event&.fetch(:created_at)])
      INSERT INTO #{TABLE} (tenant_id, command, key, origin, input_hash, result, handler, event_id, event_created_at, created_at)
      VALUES ($1, $2, $3, $4, decode(repeat('00', 32), 'hex'), '{}', $6, $7, $8, now() - make_interval(hours => $5::integer))
    SQL
    key
  end

  def delivery_of(event, dead: false)
    if dead
      @connection.exec_params(<<~SQL, [event[:handler], event[:event_id], event[:created_at], @tenant_for_seed])
        INSERT INTO vetra.dead_deliveries (handler, event_id, event_created_at, event_xid8, event_seq, event, version, tenant_id, payload, attempts)
        VALUES ($1, $2, $3, '1', 1, 'sonda.evento', 1, $4, '{}', 10)
      SQL
    else
      @connection.exec_params(<<~SQL, [event[:handler], event[:event_id], event[:created_at], @tenant_for_seed])
        INSERT INTO vetra.deliveries (handler, event_id, event_created_at, event_xid8, event_seq, tenant_id) VALUES ($1, $2, $3, '1', 1, $4)
      SQL
    end
  end

  def purge_checks
    @tenant_for_seed = tenant? ? @tenant : nil
    check_case('o papel de manutenção não escreve nem atualiza o registro, e a aplicação não o purga') do
      hash = "decode(repeat('00', 32), 'hex')"
      relay = ["INSERT INTO #{TABLE} (command, key, origin, input_hash) VALUES ('x', 'kr', 'adapter', #{hash})", "UPDATE #{TABLE} SET result = NULL"]
      relay.all? { |sql| relay_denied(sql) } && denied_app("DELETE FROM #{TABLE}")
    end
    check_case('a purga recusa limites inválidos') do
      [{ retention_hours: 0 }, { retention_hours: 8761 }, { batch: 0 }, { batch: 10_001 }, { retention_hours: '24' }].all? do |options|
        raises(Vetra::Data::Error) { @relay.purge_idempotency(**options) }
      end
    end
    check_case('a purga apaga as chaves de adaptador vencidas, em lotes, e mantém as dentro do prazo') do
      old = Array.new(5) { seed(origin: 'adapter', age_hours: 25) }
      fresh = Array.new(2) { seed(origin: 'adapter', age_hours: 1) }
      totals = @relay.purge_idempotency(retention_hours: 24, batch: 2)
      remaining = as_superuser("SELECT key FROM #{TABLE} WHERE command = 'sonda.purga'").map { |row| row['key'] }
      totals['adapter'] >= 5 && remaining.sort == fresh.sort && old.none? { |key| remaining.include?(key) }
    end
    check_case('o corte da purga não depende do fuso da sessão: com America/Sao_Paulo, 22 horas ficam e 25 saem') do
      young, old = seed(origin: 'adapter', age_hours: 22), seed(origin: 'adapter', age_hours: 25)
      @relay_db.synchronize do |connection|
        connection.exec("SET TIME ZONE 'America/Sao_Paulo'")
        begin
          @relay.purge_idempotency(retention_hours: 24)
        ensure
          connection.exec('RESET TIME ZONE')
        end
      end
      rows_of(young) == 1 && rows_of(old).zero? && begin
        @relay.purge_idempotency(retention_hours: 21)
        rows_of(young).zero?
      end
    end
    check_case('o prazo é configurável: com 48 horas, uma chave de 25 horas fica') do
      kept = seed(origin: 'adapter', age_hours: 25)
      @relay.purge_idempotency(retention_hours: 48)
      rows_of(kept) == 1 && begin
        @relay.purge_idempotency(retention_hours: 24)
        rows_of(kept).zero?
      end
    end
    if outbox?
      check_case('a chave derivada de um evento vive enquanto a entrega existir, inclusive a morta, e some depois') do
        event = ->(n) { { handler: 'sonda.handler', event_id: SecureRandom.uuid, created_at: Time.now.utc - 3600 * 40 - n } }
        pending, dead, orphan, young = Array.new(4) { |i| event.call(i) }
        delivery_of(pending)
        delivery_of(dead, dead: true)
        keys = {
          pending: seed(origin: 'event', age_hours: 30, event: pending), dead: seed(origin: 'event', age_hours: 30, event: dead),
          orphan: seed(origin: 'event', age_hours: 30, event: orphan), young: seed(origin: 'event', age_hours: 1, event: young)
        }
        @relay.purge_idempotency(retention_hours: 24)
        survived = keys.transform_values { |key| rows_of(key) }
        first = survived == { pending: 1, dead: 1, orphan: 0, young: 1 }
        # Sem a entrega, a chave derivada também sai: a pendente e a morta deixam de existir.
        @connection.exec_params('DELETE FROM vetra.deliveries WHERE event_id = $1', [pending[:event_id]])
        @connection.exec_params('DELETE FROM vetra.dead_deliveries WHERE event_id = $1', [dead[:event_id]])
        @relay.purge_idempotency(retention_hours: 24)
        first && rows_of(keys[:pending]).zero? && rows_of(keys[:dead]).zero? && rows_of(keys[:young]) == 1
      end
      check_case('a operação reivindica uma chave derivada de um evento com os dados da retenção') do
        event = { handler: 'sonda.handler', event_id: SecureRandom.uuid, event_created_at: Time.now.utc.floor }
        key = "evento:#{event[:event_id]}"
        operation(key: key, origin: :event, event: event, result: { 'ok' => true })
        row = as_superuser("SELECT origin, handler, event_id::text AS event_id FROM #{TABLE} WHERE key = $1", [key]).first
        row == { 'origin' => 'event', 'handler' => 'sonda.handler', 'event_id' => event[:event_id] }
      end
    else
      check_case('numa aplicação sem outbox só existe a origem adaptador, e a purga só a cobre') do
        @relay.purge_idempotency(retention_hours: 24) == { 'adapter' => 0 } || @relay.purge_idempotency(retention_hours: 24).keys == %w[adapter]
      end
    end
  end
end

if $PROGRAM_NAME == __FILE__
  begin
    exit(IdempotencyProbe.new(ENV.fetch('DATABASE_URL')).run ? 0 : 1)
  rescue StandardError => error
    warn "FALHA: sonda da idempotência interrompida (#{error.class})."
    exit 1
  end
end
